const payload = $json.body ?? $json;
const data = payload.data ?? payload;
const key = data.key ?? {};
const message = data.message ?? {};
const remoteJid = key.remoteJid ?? data.remoteJid ?? null;
const texto = message.conversation
  ?? message.extendedTextMessage?.text
  ?? message.imageMessage?.caption
  ?? message.videoMessage?.caption
  ?? message.documentMessage?.caption
  ?? null;

return [{
  json: {
    evento: payload.event ?? payload.type ?? null,
    instancia: payload.instance ?? null,
    telefone: remoteJid ? remoteJid.replace(/\\D/g, '') : null,
    nome: data.pushName ?? data.notifyName ?? null,
    mensagem: texto,
    tipoMensagem: data.messageType ?? null,
    mensagemDeSaida: key.fromMe ?? false,
    mensagemId: key.id ?? null,
    recebidoEm: data.messageTimestamp ?? null,
    payloadOriginal: payload
  }
}];
